import { useState, useEffect, useRef } from 'react';
import io from 'socket.io-client';
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const useSocket = (navigate, userVideo, setStream, setIsHosting, setIsJoined) => {
  const [socket, setSocket] = useState(null);
  const isMountedRef = useRef(true); // useRef to track the mounting status

  useEffect(() => {
    const newSocket = io.connect('http://localhost:3001');
    setSocket(newSocket);

    // Event listeners...
    // ...

    // Cleanup function
    return () => {
      if (!isMountedRef.current) {
        newSocket.close();
      }
    };
  }, [navigate, setStream, setIsHosting, setIsJoined, userVideo]);

  useEffect(() => {
    // When component unmounts, update isMountedRef
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  return socket;
};

export default useSocket;
